local Curves = {
    Linear = function(x) return x end,
    Quadratic = function(x) return x * x end,
    Inverse = function(x) return 1 - x end,
    Logistic = function(x) return 1 / (1 + math.exp(-12 * (x - 0.5))) end,
}

local function scoreAction(action, ctx)
    local score = 1
    for _, consideration in action.Considerations do
        local input = math.clamp(consideration.Input(ctx), 0, 1)
        local curve = Curves[consideration.Curve or 'Linear']
        score *= curve(input)
        if score <= 0 then return 0 end
    end
    -- compensation factor so actions with many considerations are not unfairly penalized
    local n = #action.Considerations
    local modification = 1 - (1 / n)
    score += (1 - score) * modification * score
    return score * (action.Weight or 1)
end

local function chooseAction(actions, ctx)
    local bestAction, bestScore = nil, -math.huge
    for _, action in actions do
        local score = scoreAction(action, ctx)
        if score > bestScore then
            bestAction, bestScore = action, score
        end
    end
    return bestAction, bestScore
end

-- Example ---------------------------------------------------------------
local actions = {
    {
        Name = 'Heal',
