            {Input = function(c) return 1 - c.Health / c.MaxHealth end, Curve = 'Quadratic'},
            {Input = function(c) return if c.HasPotion then 1 else 0 end},
        },
        Execute = function(c)
            c.Humanoid.Health = math.min(c.Humanoid.MaxHealth, c.Humanoid.Health + 25)
            c.HasPotion = false
